window.ENEM_RESOLUTION_CHUNKS=window.ENEM_RESOLUTION_CHUNKS||{};window.ENEM_RESOLUTION_CHUNKS["data/resolucoes/matematica_2021.js"]=[{"title":"Reduzir a potência usando φ²=φ+1","steps":["Do quadro, φ⁶=8φ+5.","Multiplique por φ: φ⁷=8φ²+5φ.","Substitua φ² por φ+1: φ⁷=13φ+8, opção E."],"alternatives":{"A":"5φ+3 já representa φ⁵ no quadro, não φ⁷.","B":"7φ+2 não resulta da multiplicação da expressão de φ⁶ por φ.","C":"9φ+6 não conserva a identidade φ²=φ+1 ao reduzir a potência.","D":"11φ+7 não é o par obtido pela recorrência dos coeficientes.","E":"8(φ+1)+5φ=13φ+8 é a redução correta."},"takeaway":"Se φⁿ=aφ+b, então φⁿ⁺¹=(a+b)φ+a.","key":"matematica:M329","area":"matematica","year":2021,"number":136,"answer":"E","subject":"Álgebra e Funções","topic":"Sequências, PA e PG","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[17],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Projetar um cubo na direção de uma diagonal espacial","steps":["A diagonal vertical tem projeção reduzida a um ponto, o centro.","Os outros seis vértices projetam-se num hexágono; as arestas produzem contorno e raios ao centro.","As demais diagonais projetam-se nos três diâmetros já contidos nesses raios: E."],"alternatives":{"A":"Os segmentos internos adicionais não correspondem à projeção ortogonal na direção da diagonal.","B":"O contorno não é quadrangular nessa orientação do cubo.","C":"O retângulo com diagonais corresponderia a outra orientação de observação.","D":"Uma vista quadrada simples não é obtida com a diagonal espacial perpendicular ao solo.","E":"O hexágono dividido em seis triângulos reúne as projeções sem acrescentar linhas indevidas."},"takeaway":"Em projeção ortogonal, uma reta perpendicular ao plano projeta-se num ponto.","key":"matematica:M505","area":"matematica","year":2021,"number":137,"answer":"E","subject":"Geometria espacial","topic":"Visualização espacial, cortes e projeções","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[17],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Questão anulada: distinguir as placas antes de contar","steps":["O gabarito oficial registra Anulada: não há alternativa correta oficial a escolher nem ponto de acerto a atribuir.","Como exercício independente, as placas incluem o ano e podem ser tratadas como distintas; há 7 gaúchas, 5 cariocas, 7 mineiras e 9 paulistas.","Nesse modelo, as quatro linhas restritas podem ser preenchidas por A(7,5)·5!·A(7,5)·A(9,5); as dez placas restantes ocupam as duas últimas linhas em 10! ordens. Esta é análise didática, não motivo oficial da anulação."],"alternatives":{"A":"Divisões por títulos repetidos tratam placas do mesmo clube como indistinguíveis, embora o ano as diferencie no modelo descrito.","B":"Os fatores 7! e 9! não selecionam corretamente apenas cinco posições de cada grupo com excedentes.","C":"30! permitiria qualquer ordem e ignoraria as restrições estaduais das primeiras linhas.","D":"Combinações selecionam conjuntos, mas deixam de contar as ordens nas linhas e os dez lugares finais.","E":"O primeiro fator envolve nove objetos, embora existam sete placas gaúchas; não é a contagem desse modelo."},"takeaway":"Anulação oficial não autoriza inventar uma letra ou um motivo oficial; separe o registro oficial da análise pedagógica.","key":"matematica:M756","area":"matematica","year":2021,"number":138,"answer":"Anulada","subject":"Probabilidade e Análise combinatória","topic":"Contagem e análise combinatória","status":"verified","annulled":true,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[18],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Mesmo número de franquias permite comparar os totais","steps":["As cinco médias têm denominador 3.","Some cada coluna: I=1245, II=1230, III=1220, IV=1233, V=1280.","O maior total e a maior média são de V: E."],"alternatives":{"A":"I tem média 415, inferior à de V, aproximadamente 426,67.","B":"II totaliza 1230 unidades e tem média de apenas 410 por franquia.","C":"III totaliza 1220, o menor total entre os cinco tipos.","D":"IV tem média 411, apesar de apresentar a maior venda isolada na terceira franquia.","E":"V tem o maior total, 1280, e portanto a maior média por franquia."},"takeaway":"Não escolha a maior célula: a decisão depende das vendas combinadas nas três franquias.","key":"matematica:M650","area":"matematica","year":2021,"number":139,"answer":"E","subject":"Estatística","topic":"Média, mediana e moda","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[19],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Ponderar faturamentos pelo número de meses","steps":["O total anual é 3,5·3+2,5·2+5·2+3·4+7,5·1=45 milhões.","Há 12 meses: M=45/12=3,75 milhões.","Como 2≤M<4, a comissão é II, alternativa B."],"alternatives":{"A":"A faixa I exige média inferior a 2 milhões, abaixo dos 3,75 calculados.","B":"A média 3,75 está entre 2 e 4 milhões, sem atingir 4.","C":"A faixa III começa em 4 milhões, acima da média anual.","D":"A faixa IV começa em 5 milhões, acima da média anual.","E":"O mês de 7,5 milhões não determina sozinho uma média de pelo menos 6."},"takeaway":"Média de valores com frequências diferentes exige pesos, não a média simples dos valores distintos.","key":"matematica:M651","area":"matematica","year":2021,"number":140,"answer":"B","subject":"Estatística","topic":"Média, mediana e moda","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[19],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Separar diária, taxa fixa e percentual","steps":["As diárias somam d·n.","A limpeza acrescenta L uma única vez; o serviço vale s·d·n, com s escrito como taxa decimal.","Logo P=dn+L+dns, alternativa A."],"alternatives":{"A":"Inclui n diárias, uma limpeza e serviço percentual sobre todas as diárias.","B":"ds considera o serviço de apenas uma diária, e não das n diárias.","C":"Faltam n e a base de cálculo do percentual de serviço.","D":"Contém o serviço e a limpeza, mas omite o preço principal das diárias.","E":"Soma diretamente a taxa s como se ela fosse um valor monetário fixo."},"takeaway":"Antes de montar o modelo, identifique a base sobre a qual incide cada percentual.","key":"matematica:M267","area":"matematica","year":2021,"number":141,"answer":"A","subject":"Álgebra e Funções","topic":"Função afim e modelos lineares","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[19],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Pelo menos um acerto é o complemento de nenhum","steps":["No modelo de lançamentos independentes, errar todos os n dardos tem probabilidade (1/2)ⁿ.","Assim P(pontuar)=1−(1/2)ⁿ≥0,9.","Com n=3, dá 0,875; com n=4, 0,9375. O mínimo é 4: B."],"alternatives":{"A":"Com dois dardos, a probabilidade é 1−1/4=0,75, insuficiente.","B":"Quatro dardos atingem 0,9375, enquanto três ainda não atingem 0,9.","C":"Seis dardos atendem ao limite, mas não constituem o mínimo.","D":"Nove dardos superam o limite com quantidade maior que a necessária.","E":"Dez dardos também atendem, mas quatro já bastam."},"takeaway":"Em eventos pelo menos um, o complementar costuma evitar a soma de muitos casos.","key":"matematica:M708","area":"matematica","year":2021,"number":142,"answer":"B","subject":"Probabilidade e Análise combinatória","topic":"Probabilidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[19],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Volume é capacidade multiplicada pela ocupação","steps":["Leia as ocupações I=20%, II=30%, III=50%, IV=40%, V=60%.","Os volumes são, em bilhões de litros: 21, 30, 10, 32 e 24.","IV tem o maior volume absoluto, 32: D."],"alternatives":{"A":"I tem a maior capacidade, mas apenas 21 bilhões de litros armazenados.","B":"II armazena 30 bilhões, menos que os 32 de IV.","C":"III tem metade de sua capacidade ocupada, mas armazena só 10 bilhões.","D":"IV reúne 80 bilhões de capacidade e 40% de ocupação, totalizando 32 bilhões.","E":"V tem maior percentual de ocupação, mas armazena 24 bilhões."},"takeaway":"Percentuais de bases diferentes precisam ser convertidos em valores absolutos para comparação.","key":"matematica:M562","area":"matematica","year":2021,"number":143,"answer":"D","subject":"Estatística","topic":"Leitura de gráficos e tabelas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[20],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Cada idade precisa ser ponderada por sua frequência","steps":["O gráfico mostra 6 alunos de 9 anos, 12 de 18 e 9 de 27.","A soma das idades é 9·6+18·12+27·9=513.","Divida pelos 27 alunos: 513/27=19 anos, alternativa D."],"alternatives":{"A":"9 é a menor idade observada, não a média ponderada.","B":"12 é uma frequência do gráfico, não a média de idade.","C":"18 é a média simples das três idades distintas, mas ignora suas frequências.","D":"19 resulta da soma ponderada dividida pela quantidade total de alunos.","E":"27 é a maior idade da amostra, não sua média."},"takeaway":"No gráfico de frequências, a altura da barra é um peso e não uma nova idade.","key":"matematica:M652","area":"matematica","year":2021,"number":144,"answer":"D","subject":"Estatística","topic":"Média, mediana e moda","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[20],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"As porcentagens somam cem e ponderam o tempo","steps":["Há dois grupos com x% e um com y%: 2x+y=100.","A média geral de seis minutos dá 3x+5y+12x=600.","Substituindo y=100−2x: 5x=100, então x=20 e y=60: C."],"alternatives":{"A":"10 e 80 somam 100 com os dois grupos x, mas produzem média de apenas 5,5 minutos.","B":"10 e 90 dão 110% ao contar duas vezes o grupo x.","C":"20, 60 e 20 somam 100% e produzem média 0,2·3+0,6·5+0,2·12=6.","D":"20, 80 e 20 somam 120%, contrariando a distribuição.","E":"25, 50 e 25 somam 100%, mas produzem média de 6,25 minutos."},"takeaway":"Quando há grupos de mesmo percentual, conte cada grupo separadamente na soma e na média.","key":"matematica:M563","area":"matematica","year":2021,"number":145,"answer":"C","subject":"Estatística","topic":"Leitura de gráficos e tabelas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[20],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Comparar dispersões relativas, não só desvios","steps":["O coeficiente atual é 1/10=0,10.","A nova ração deve ter 1,5/x<0,10.","Como x>0, resulta x>15 kg, alternativa E."],"alternatives":{"A":"Acima de 5 kg não assegura CV menor que 0,10.","B":"Uma média pouco acima de 9,5 ainda pode gerar CV próximo de 0,15.","C":"Superar 10 kg não compensa necessariamente o desvio de 1,5 kg.","D":"Com 10,5 kg o CV ainda é aproximadamente 0,143, maior que o atual.","E":"Em 15 kg os CVs se igualam; é preciso média estritamente maior que 15."},"takeaway":"Coeficiente de variação compara desvio padrão à média; maior desvio absoluto pode coexistir com menor dispersão relativa.","key":"matematica:M653","area":"matematica","year":2021,"number":146,"answer":"E","subject":"Estatística","topic":"Média, mediana e moda","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[20],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A cifra desloca rótulos, não as frequências","steps":["No gráfico original, as quatro letras mais frequentes são A, E, O e S, nessa ordem.","Desloque cada uma três casas: A→D, E→H, O→R, S→V.","A ordem das frequências permanece: D, H, R, V, opção C."],"alternatives":{"A":"A, E, O e S são as letras originais, antes da codificação.","B":"D, E, F e G correspondem a deslocar letras consecutivas, não as mais frequentes.","C":"Os quatro rótulos são corretamente deslocados mantendo a ordem das frequências.","D":"A sequência não é obtida ao somar três posições às quatro letras originais mais frequentes.","E":"As letras apresentadas não correspondem ao deslocamento pedido."},"takeaway":"Uma substituição bijetiva de letras preserva quantas vezes cada símbolo aparece.","key":"matematica:M564","area":"matematica","year":2021,"number":147,"answer":"C","subject":"Estatística","topic":"Leitura de gráficos e tabelas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[21],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Em doze valores a mediana usa duas posições","steps":["Ordene: 11,11,12,13,15,15,16,16,17,18,20,24.","As posições centrais são a sexta e a sétima: 15 e 16.","Mediana=(15+16)/2=15,5, alternativa C."],"alternatives":{"A":"11 é um dos valores mais frequentes, não o centro da lista ordenada.","B":"15 é apenas o primeiro dos dois valores centrais.","C":"15,5 é a média das posições 6 e 7 após ordenar os doze dados.","D":"15,7 se aproxima da média aritmética dos dados, mas não da mediana.","E":"17,5 resulta de usar valores fora das duas posições centrais."},"takeaway":"Ordene os dados antes de escolher as posições centrais; a ordem dos anos não ordena as contagens.","key":"matematica:M654","area":"matematica","year":2021,"number":148,"answer":"C","subject":"Estatística","topic":"Média, mediana e moda","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[21],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O maior lucro é a maior distância receita menos despesa","steps":["Leia receita e despesa em cada mês.","Os lucros são 5,10,5,5 e 3 milhões, de janeiro a maio.","O máximo é fevereiro, e o patamar futuro deve ser pelo menos 10 milhões: B."],"alternatives":{"A":"Janeiro teve lucro de 10−5=5 milhões, inferior ao máximo.","B":"Fevereiro teve 20−10=10 milhões, o maior lucro observado.","C":"Março teve 15−10=5 milhões, abaixo de fevereiro.","D":"Abril teve 20−15=5 milhões, não o máximo.","E":"Maio teve maior receita, mas seu lucro foi apenas 28−25=3 milhões."},"takeaway":"Maior receita não implica maior lucro: desconte a despesa de cada período.","key":"matematica:M565","area":"matematica","year":2021,"number":149,"answer":"B","subject":"Estatística","topic":"Leitura de gráficos e tabelas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[22],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O denominador do aumento é o valor inicial","steps":["O volume passa de 236 para 519,2 milhões.","O aumento absoluto é 283,2 milhões.","Aumento percentual=283,2/236·100=120%, alternativa C."],"alternatives":{"A":"45,4% é aproximadamente a razão do valor inicial pelo final, não o aumento.","B":"54,5% usa o aumento em relação ao valor final, em vez do inicial.","C":"O acréscimo equivale a 1,2 vez o valor inicial, isto é, 120%.","D":"220% é o valor final como percentual do inicial, não somente o crescimento.","E":"283,2 é a diferença em milhões, não uma taxa percentual."},"takeaway":"Percentual de aumento = (final−inicial)/inicial × 100.","key":"matematica:M079","area":"matematica","year":2021,"number":150,"answer":"C","subject":"Aritmética e Matemática básica","topic":"Porcentagem e variações percentuais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[22],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Acumular as frequências até ultrapassar metade","steps":["Metade de 105 é 52,5; a posição mediana é a 53ª.","As frequências acumuladas até 600, 700 e 800 mil são 20, 35 e 55.","A 53ª observação está na faixa ]700,800]; entre os limites oferecidos, a resposta esperada é 800: C. O histograma não fornece os preços individuais dentro da faixa."],"alternatives":{"A":"Até 600 mil acumulam-se 20 imóveis, muito menos que a metade.","B":"Até 700 mil há 35 imóveis, ainda abaixo dos 53 necessários.","C":"O limite de 800 mil encerra a faixa que contém a posição 53, conforme a leitura agrupada da prova.","D":"900 mil já ultrapassa o primeiro limite de classe que atende à contagem.","E":"Um milhão é um limite posterior ao necessário para atingir metade dos imóveis."},"takeaway":"Um histograma localiza a faixa da mediana; não determina seu valor individual exato nem resolve empates no limite.","key":"matematica:M655","area":"matematica","year":2021,"number":151,"answer":"C","subject":"Estatística","topic":"Média, mediana e moda","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[22],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Aplicar a operação estrela depois da operação triângulo","steps":["Com b=1, faça u=a²+a−1 e v=1+a−a².","Como u*v=uv+u=u(v+1), a equação é (a²+a−1)(2+a−a²)=0.","As raízes são (−1±√5)/2, −1 e 2; as duas maiores são (−1+√5)/2 e 2, cuja soma é (3+√5)/2: E."],"alternatives":{"A":"√5 é a diferença entre as raízes de a²+a−1, não a soma das duas maiores raízes da equação completa.","B":"√3 não é a soma obtida ao resolver os dois fatores quadráticos.","C":"√1=1 não é a soma das duas maiores soluções, que é aproximadamente 2,618.","D":"(−1+√5)/2 é apenas uma das duas maiores soluções, faltando adicionar 2.","E":"(3+√5)/2 soma corretamente 2 e (−1+√5)/2."},"takeaway":"Operações novas são definidas pelo enunciado: substitua com parênteses antes de aplicar regras usuais.","key":"matematica:M233","area":"matematica","year":2021,"number":152,"answer":"E","subject":"Álgebra e Funções","topic":"Equações, sistemas e inequações","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[23],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Uniformizar as unidades antes de formar a razão","steps":["O comprimento real é 38,4 m=3840 cm.","A razão miniatura/real é 160/3840=1/24.","A largura confirma: 7/168=1/24. A escala é 1:24, opção C."],"alternatives":{"A":"576 é 24²; escala linear não exige elevar a razão ao quadrado.","B":"240 resulta de erro de fator dez na conversão das unidades.","C":"As duas medidas da réplica são 24 vezes menores que as reais.","D":"4,2 não é a razão obtida por nenhuma das duas medidas correspondentes.","E":"2,4 resulta de perder um fator dez ao converter metros em centímetros."},"takeaway":"Escala linear relaciona comprimentos correspondentes na mesma unidade.","key":"matematica:M127","area":"matematica","year":2021,"number":153,"answer":"C","subject":"Aritmética e Matemática básica","topic":"Escalas e conversões de unidades","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[23],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Projetar os acréscimos e depois calcular a razão","steps":["Médicos aumentam 73000 em cada década; população aumenta 23 e 21 milhões.","A projeção acrescenta 73000 médicos e 22 milhões de habitantes: 438000 e 213 milhões em 2020.","Médicos por mil=438000/213000000·1000≈2,06, alternativa D."],"alternatives":{"A":"0,17 fica muito abaixo da razão calculada com os totais projetados.","B":"0,49 não corresponde à divisão dos 438 mil médicos por 213 milhões de habitantes.","C":"1,71 aproxima a razão de 2000, não a projeção para 2020.","D":"438/213≈2,06 médicos por mil habitantes é o valor projetado.","E":"3,32 supera a razão obtida com os acréscimos absolutos indicados."},"takeaway":"A população já está em milhares na tabela; mantenha consistência entre unidades ao formar o indicador.","key":"matematica:M566","area":"matematica","year":2021,"number":154,"answer":"D","subject":"Estatística","topic":"Leitura de gráficos e tabelas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[23],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O aumento da batata precisa ser compensado no frango","steps":["O frango custa 0,4·12,50=R$5,00; batata custa R$3,00 e hortaliça R$2,00.","A batata passa a R$4,50, aumentando a refeição em R$1,50.","É preciso retirar R$1,50 dos R$5,00 do frango: 30%, opção C; restam 280 g."],"alternatives":{"A":"12,5 não é a razão entre o gasto adicional de R$1,50 e os R$5,00 de frango.","B":"280 g é a massa restante de frango, não uma redução de 28%.","C":"Retirar 30% de 400 g, isto é, 120 g, economiza exatamente R$1,50.","D":"50% é a alta da batata, não a redução necessária no frango.","E":"70% é a fração de frango mantida, não a fração retirada."},"takeaway":"Percentuais sobre produtos diferentes não se transferem diretamente: compare os valores monetários.","key":"matematica:M080","area":"matematica","year":2021,"number":155,"answer":"C","subject":"Aritmética e Matemática básica","topic":"Porcentagem e variações percentuais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[24],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Ler amplitude, posição inicial e período","steps":["O gráfico oscila de −3 a 3: amplitude 3.","Em t=0, P=−3; isso seleciona um cosseno negativo.","Os mínimos se repetem a cada π segundos, logo ω=2π/π=2 e P(t)=−3cos(2t): A."],"alternatives":{"A":"Tem amplitude 3, mínimo inicial −3 e período π, como o gráfico.","B":"O seno vale zero em t=0 e não reproduz a posição inicial.","C":"O cosseno positivo começa em +3, o oposto da posição inicial.","D":"A amplitude seria 6, quando o deslocamento máximo em módulo é 3.","E":"Além de começar no zero, o seno com coeficiente 6 tem amplitude excessiva."},"takeaway":"A distância entre máximo e mínimo é 2A; não a confunda com a amplitude.","key":"matematica:M792","area":"matematica","year":2021,"number":156,"answer":"A","subject":"Trigonometria","topic":"Funções trigonométricas e fenômenos periódicos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[24],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Destino corresponde à coluna da matriz","steps":["aᵢⱼ conta famílias que saem de i e chegam a j.","Some cada coluna para medir chegadas, sem descontar saídas.","Os totais em dezenas são 4,8,10,11 e 12; vence a região 5: E."],"alternatives":{"A":"A região 1 recebe 4 dezenas de famílias, abaixo das demais.","B":"A região 2 recebe 8 dezenas, não o maior fluxo de chegada.","C":"A região 3 recebe 10 dezenas, menos que as regiões 4 e 5.","D":"A região 4 recebe 11 dezenas, ainda abaixo da região 5.","E":"A coluna 5 soma 5+3+0+4+0=12 dezenas, o maior total."},"takeaway":"Linha é origem e coluna é destino nesse modelo; saldo e fluxo de entrada são indicadores diferentes.","key":"matematica:M567","area":"matematica","year":2021,"number":157,"answer":"E","subject":"Estatística","topic":"Leitura de gráficos e tabelas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[25],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Os dois fatores percentuais se multiplicam","steps":["A transporta 200 passageiros; B transporta 220.","O consumo por passageiro cai de 0,02 para 0,018 L/km.","A razão total é 1,10·0,90=0,99: 1% menor, alternativa B; no percurso, 8000 L contra 7920 L."],"alternatives":{"A":"10% menor ignora que a lotação também aumentou em 10%.","B":"A multiplicação dos fatores dá 99% do consumo anterior, redução de 1%.","C":"Percentuais opostos não se anulam quando incidem sobre grandezas multiplicativas.","D":"O produto é 0,99, não 1,01: houve pequena redução.","E":"11% maior contraria o efeito combinado de lotação e rendimento."},"takeaway":"Aumento de 10% e redução de 10% em fatores de um produto geram fator 0,99.","key":"matematica:M014","area":"matematica","year":2021,"number":158,"answer":"B","subject":"Aritmética e Matemática básica","topic":"Razão, proporção e regra de três","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[25],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O serviço paralelo termina quando o grupo mais lento termina","steps":["Um pneu demanda 3·4=12 pessoas·segundo, no modelo de produtividade dado.","O grupo reduzido tem 2 pessoas e leva 12/2=6 s.","Os outros três acabam em 4 s, mas é preciso aguardar os 6 s do último: A."],"alternatives":{"A":"6 s é o tempo do grupo reduzido e determina a conclusão das quatro trocas simultâneas.","B":"5,7 s não completa o trabalho de 12 pessoas·segundo com apenas duas pessoas.","C":"5 s ainda é inferior aos 6 s necessários ao grupo com dois trabalhadores.","D":"4,5 s não satisfaz a proporcionalidade inversa para o grupo reduzido.","E":"4,4 s aproxima um cálculo com o total de funcionários, ignorando a separação dos grupos."},"takeaway":"Em tarefas paralelas sem redistribuição de trabalhadores, o tempo final é o máximo dos tempos dos grupos.","key":"matematica:M015","area":"matematica","year":2021,"number":159,"answer":"A","subject":"Aritmética e Matemática básica","topic":"Razão, proporção e regra de três","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[25],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O mineral limitante determina o número de sachês","steps":["Para cada tipo, calcule o maior entre 800/A, 1000/B e 1200/C e arredonde para cima.","As quantidades mínimas são I=16, II=6, III=4, IV=2, V=2.","Os custos são R$32, R$18, R$20, R$12 e R$16; o menor é IV, opção D."],"alternatives":{"A":"I exige 16 sachês por causa do mineral A, custando R$32.","B":"II exige 6 sachês por causa do mineral C, custando R$18.","C":"III exige 4 sachês para atender A e C, custando R$20.","D":"Dois sachês IV fornecem 1200, 1000 e 2000 mg por R$12, o menor custo.","E":"V precisa de dois sachês por causa do mineral A, totalizando R$16."},"takeaway":"Não compare apenas o preço unitário: calcule quantas unidades cumprem simultaneamente todas as exigências.","key":"matematica:M817","area":"matematica","year":2021,"number":160,"answer":"D","subject":"Matemática financeira","topic":"Descontos, preços e comparação de propostas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[25],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A receita é quadrática, mas o domínio é discreto","steps":["Com desconto inteiro x, o preço é 20−x e o público 200+40x.","R(x)=(20−x)(200+40x)=−40x²+600x+4000, para descontos inteiros admissíveis.","A concavidade é para baixo; o máximo contínuo está em 7,5 e os inteiros 7 e 8 dão R$6240. E mostra pontos, não curva contínua."],"alternatives":{"A":"A reta crescente ignora o produto entre preço decrescente e público crescente.","B":"Os pontos respeitam a restrição de inteiros, mas descrevem crescimento linear incorreto.","C":"A reta decrescente não representa o crescimento inicial da arrecadação.","D":"A parábola tem forma apropriada, mas a curva contínua ignora os descontos obrigatoriamente inteiros.","E":"Os pontos sobre uma parábola côncava para baixo representam corretamente o domínio discreto."},"takeaway":"Modelo quadrático não obriga gráfico contínuo: confira se a variável pode assumir valores fracionários.","key":"matematica:M289","area":"matematica","year":2021,"number":161,"answer":"E","subject":"Álgebra e Funções","topic":"Função quadrática","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[26],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O imposto é contínuo e muda de inclinação","steps":["Até R$5000, I=0.","De 5000 a 10000, I=0,1(R−5000), chegando a 500.","Depois I=500+0,3(R−10000), chegando a 2000 em R=15000. A reúne os três trechos."],"alternatives":{"A":"Mostra isenção inicial, subida até 500 e inclinação maior até 2000.","B":"Mantém a mesma inclinação depois de 10000 e termina em 1000, não 2000.","C":"Cobra imposto desde o início e não preserva a faixa de isenção.","D":"Transforma o imposto em valores constantes por faixa, quando ele varia com R.","E":"Omite a faixa inicial e mantém inclinação que não acompanha os 30% marginais."},"takeaway":"Alíquota marginal incide no excedente da faixa; não no preço inteiro do produto.","key":"matematica:M345","area":"matematica","year":2021,"number":162,"answer":"A","subject":"Álgebra e Funções","topic":"Leitura e transformação de gráficos de funções","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[27],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Multiplicar unidades também exige elevar ao quadrado","steps":["A relação é módulo=k·ρ·v², com k adimensional.","Unidades: (kg·m⁻³)(m·s⁻¹)².","Somando expoentes, obtém-se kg·m⁻¹·s⁻², opção B, equivalente a pascal."],"alternatives":{"A":"O fator v deve ser elevado ao quadrado; s⁻¹ não é o expoente final.","B":"kg·m⁻³·m²·s⁻²=kg·m⁻¹·s⁻² é a unidade correta.","C":"Os expoentes de metro e segundo não resultam de multiplicar densidade por velocidade ao quadrado.","D":"A densidade está multiplicando, e não dividindo, portanto kg não fica no denominador.","E":"Inverter a massa e acrescentar m⁵ não corresponde à relação apresentada."},"takeaway":"Análise dimensional aplica as mesmas regras de potências usadas na álgebra.","key":"matematica:M128","area":"matematica","year":2021,"number":163,"answer":"B","subject":"Aritmética e Matemática básica","topic":"Escalas e conversões de unidades","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[28],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Comparar as duas malas elimina a massa da própria mala","steps":["Sejam c, p e s as massas de camiseta, calça e sapato; a mala é a mesma.","Subtrair as duas combinações dá 6c=p+s.","Da segunda viagem, retirar uma calça e um sapato permite acrescentar seis camisetas: 18+6=24, opção B."],"alternatives":{"A":"22 camisetas não utilizam toda a massa que a retirada de uma calça e um sapato libera.","B":"24 camisetas, duas calças e um sapato mantêm a mesma massa total de 10 kg.","C":"26 camisetas excedem a substituição equivalente de seis camisetas.","D":"33 camisetas acrescentam mais massa que a retirada da calça e do sapato.","E":"39 camisetas também ultrapassam a equivalência obtida das duas viagens."},"takeaway":"Subtrair situações com totais iguais revela equivalências sem precisar conhecer cada massa individual.","key":"matematica:M234","area":"matematica","year":2021,"number":164,"answer":"B","subject":"Álgebra e Funções","topic":"Equações, sistemas e inequações","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[28],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Economia em litros deve ser calculada antes do novo rendimento","steps":["O motor antigo gasta 20/16=1,25 L em 20 km.","O novo gasta 1,25−0,10=1,15 L nesse percurso.","O desempenho é 20/1,15≈17,4 km/L, alternativa D."],"alternatives":{"A":"Economizar combustível deve aumentar o valor em km/L, não reduzi-lo para 15,9.","B":"Somar 0,1 a 16 mistura uma economia em litros com um rendimento em km/L.","C":"16,4 não resulta da divisão da distância pelo novo consumo de 1,15 L.","D":"20 km divididos por 1,15 L dão aproximadamente 17,4 km/L.","E":"18,0 superestima o rendimento obtido com a economia indicada."},"takeaway":"Litros por quilômetro e quilômetros por litro são grandezas inversas, não equivalentes.","key":"matematica:M016","area":"matematica","year":2021,"number":165,"answer":"D","subject":"Aritmética e Matemática básica","topic":"Razão, proporção e regra de três","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[28],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Paredes e piso não têm o mesmo fator de área","steps":["Paredes: a área total dos dois lados é 4h(c+l).","Dobrar c e l, mantendo h, dobra essa área.","O piso passa de cl para (2c)(2l)=4cl. O fornecedor II está correto: B."],"alternatives":{"A":"O piso quadruplica, porque suas duas dimensões dobram.","B":"O dobro para paredes e quatro vezes para piso são os fatores corretos.","C":"A altura das paredes permanece fixa, portanto sua área não quadruplica.","D":"Os fatores estão trocados: o piso cresce mais que a área lateral.","E":"Oito vezes seria um fator volumétrico de ampliação em três dimensões, que não ocorreu."},"takeaway":"Antes de aplicar um fator de escala, verifique exatamente quais dimensões foram alteradas.","key":"matematica:M485","area":"matematica","year":2021,"number":166,"answer":"B","subject":"Geometria espacial","topic":"Áreas de superfícies e planificações","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[28],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Dimensionar o cilindro pelo consumo de sete dias","steps":["O volume necessário é 100·120·7=84000 L=84 m³.","Diâmetro 5 m dá raio 2,5 m e área de base 3·2,5²=18,75 m².","A altura é 84/18,75=4,48 m, alternativa D."],"alternatives":{"A":"1,12 m resulta de tratar o diâmetro 5 m como raio e quadruplicar a área.","B":"3,10 m não produz os 84 m³ necessários com raio 2,5 m.","C":"4,35 m oferece volume menor que o consumo de sete dias.","D":"18,75·4,48=84 m³, exatamente a demanda do período.","E":"5,60 m excede a altura mínima necessária para os sete dias."},"takeaway":"Converta litros para metros cúbicos e transforme diâmetro em raio antes de usar V=πr²h.","key":"matematica:M446","area":"matematica","year":2021,"number":167,"answer":"D","subject":"Geometria espacial","topic":"Volumes e capacidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[28],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Face oposta não compartilha nenhum vértice","steps":["Um octaedro regular tem oito faces e cada face tem uma única oposta.","Apenas não compartilhar aresta é insuficiente: duas faces ainda podem encontrar-se num vértice.","Ao dobrar a cadeia de triângulos, a face 4 fica com os três vértices complementares aos da cinza; 1, 2 e 3 conservam algum vértice comum. Logo E."],"alternatives":{"A":"Uma face triangular tem uma única face oposta nesse sólido, não quatro.","B":"As faces 1 e 3 não são ambas opostas; compartilham vértices com a cinza após a montagem.","C":"A face 1 não fica com três vértices distintos dos da face cinza.","D":"A face 2 também conserva vértice em comum após dobrar a planificação.","E":"A face 4 é a única das numeradas sem vértice ou aresta em comum com a cinza."},"takeaway":"Na planificação, distância no papel não determina oposição: acompanhe os vértices durante a dobra.","key":"matematica:M486","area":"matematica","year":2021,"number":168,"answer":"E","subject":"Geometria espacial","topic":"Áreas de superfícies e planificações","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[29],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A barra conserva o perímetro do equilátero","steps":["Para lado a, a altura é h=a√3/2.","O perímetro é 3a=6h/√3=2h√3.","Com h=8 cm e √3≈1,7, resulta P≈27,2 cm; o valor mais próximo é 27,18 cm: D."],"alternatives":{"A":"9,07 cm é próximo da medida de um lado, não do perímetro total.","B":"13,60 cm corresponde a h√3, apenas metade do perímetro.","C":"20,40 cm não resulta de 2h√3 com a altura dada.","D":"27,18 cm é a opção mais próxima do perímetro aproximado de 27,2 cm.","E":"36,24 cm supera o comprimento total obtido da relação entre lado e altura."},"takeaway":"Simplifique algebricamente antes de inserir aproximações, evitando diferenças por arredondamento intermediário.","key":"matematica:M419","area":"matematica","year":2021,"number":169,"answer":"D","subject":"Geometria plana","topic":"Ângulos, circunferências e polígonos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[29],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A caneca é um tronco de cone","steps":["Os raios são R=5 cm e r=4 cm, e h=12 cm.","Use V=πh(R²+Rr+r²)/3.","Com π=3: V=12(25+20+16)=732 cm³=732 mL, alternativa C."],"alternatives":{"A":"216 mL não corresponde ao volume obtido com os dois raios e a altura informados.","B":"408 mL subestima o tronco e não aplica a expressão completa.","C":"732 mL resulta corretamente da soma R²+Rr+r² e do fator πh/3.","D":"2196 é três vezes o volume correto, como ao omitir o divisor 3.","E":"2928 pode resultar de usar diâmetros como raios, quadruplicando o volume."},"takeaway":"Em tronco de cone, não substitua a fórmula pela de um cilindro de raio médio.","key":"matematica:M447","area":"matematica","year":2021,"number":170,"answer":"C","subject":"Geometria espacial","topic":"Volumes e capacidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[29],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Escolher a maior área dentro do teto de custo","steps":["A R$0,01/cm², o teto R$0,80 permite até 80 cm².","Áreas aproximadas: triângulo 61,2; quadrado 64; retângulo 88; hexágono 91,8; círculo 75 cm².","Retângulo e hexágono excedem o orçamento; círculo tem a maior área admissível, E."],"alternatives":{"A":"O triângulo custa aproximadamente R$0,612, mas oferece menos área que o círculo.","B":"O quadrado custa R$0,64 e tem 64 cm², menos que os 75 do círculo.","C":"O retângulo tem 88 cm² e custaria R$0,88, acima do limite.","D":"O hexágono tem aproximadamente 91,8 cm² e excede o teto de R$0,80.","E":"O círculo tem raio 5 cm, área 3·25=75 cm² e custo R$0,75."},"takeaway":"Otimizar com restrição exige eliminar opções inviáveis antes de escolher a maior medida.","key":"matematica:M371","area":"matematica","year":2021,"number":171,"answer":"E","subject":"Geometria plana","topic":"Áreas e perímetros","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[29],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Calcular os dois limites da faixa aeróbica","steps":["A frequência máxima estimada é 220−61=159 bpm.","65% de 159=103,35 e 85%=135,15 bpm.","Somente 120 e 130 estão na faixa: forte no plano e subida moderada, D."],"alternatives":{"A":"Inclui 90 e 140 bpm, respectivamente abaixo e acima da faixa calculada.","B":"Inclui o trecho leve de 90 bpm, abaixo do mínimo de 103,35.","C":"Inclui subida forte de 140 bpm, acima do máximo de 135,15.","D":"120 e 130 bpm estão entre 103,35 e 135,15, como exige o modelo.","E":"Os dois trechos indicados são justamente os que ficam fora da faixa."},"takeaway":"Use a fórmula fornecida como modelo do item; ela não substitui avaliação médica individual.","key":"matematica:M568","area":"matematica","year":2021,"number":172,"answer":"D","subject":"Estatística","topic":"Leitura de gráficos e tabelas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[30],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Para minimizar a quantidade, usar o maior preço por lavagem","steps":["Cada lavagem rende no máximo R$35.","Com oito, a receita máxima é 8·35=R$280, insuficiente.","Nove bastam: oito completas e uma simples rendem R$300. O mínimo é 9, opção C."],"alternatives":{"A":"Mesmo seis lavagens completas rendem só R$210.","B":"Oito lavagens completas rendem no máximo R$280, abaixo do necessário.","C":"Nove permitem atingir R$300 e oito não, provando a minimalidade.","D":"Quinze simples atingem a meta, mas não minimizam o número de serviços.","E":"Vinte lavagens são desnecessárias, já que nove podem cobrir a meta."},"takeaway":"Para provar um mínimo inteiro, mostre que o anterior é impossível e dê um exemplo viável no mínimo.","key":"matematica:M211","area":"matematica","year":2021,"number":173,"answer":"C","subject":"Aritmética e Matemática básica","topic":"Raciocínio lógico e otimização aritmética","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[30],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Aplicar cada desconto somente quando sua condição é atendida","steps":["Na farmácia 2, comprar X e Y juntos custa 0,8(50+50)=R$80.","Comprar Z na farmácia 3 custa R$35, totalizando R$115.","Compare as opções: A=135, B=120, C=115, D=130, E=116. O mínimo é C."],"alternatives":{"A":"Os três na farmácia 1 custam 45+40+50=R$135.","B":"X e Y na farmácia 1 mais Z na 3 custam 45+40+35=R$120.","C":"X e Y com desconto na 2 e Z na 3 totalizam R$115, o menor custo.","D":"Sem Y na farmácia 2, X não ganha o desconto: 50+45+35=R$130.","E":"Os três na farmácia 3 custam 0,8(65+45+35)=R$116, um real a mais que C."},"takeaway":"Desconto condicionado exige comparar pacotes de compra, não escolher isoladamente cada preço de tabela.","key":"matematica:M818","area":"matematica","year":2021,"number":174,"answer":"C","subject":"Matemática financeira","topic":"Descontos, preços e comparação de propostas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[30],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Separar as faces dos cubos e as ligações entre eles","steps":["A estrutura contém um cubo externo e um interno, com vértices correspondentes conectados.","Cada cubo tem seis faces quadradas, totalizando doze quadrados.","Cada uma das doze arestas externas forma com a correspondente interna um trapézio isósceles: doze trapézios, alternativa A."],"alternatives":{"A":"São 6+6 quadrados e um trapézio isósceles por par de arestas correspondentes, total de 12.","B":"Contar o mesmo trapézio a partir dos dois cubos duplica indevidamente os 12 em 24.","C":"Nos quadriláteros de ligação, só um par de lados é paralelo; não são paralelogramos.","D":"Oito é a quantidade de vértices de cada cubo, não o número de trapézios de ligação.","E":"A congruência das hastes de ligação dá trapézios isósceles; as faces dos cubos são quadrados."},"takeaway":"Na contagem espacial, classifique uma família de figuras de cada vez e evite contar duas vezes a mesma região.","key":"matematica:M506","area":"matematica","year":2021,"number":175,"answer":"A","subject":"Geometria espacial","topic":"Visualização espacial, cortes e projeções","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[30],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Ler os blocos romanos e depois subtrair","steps":["MCDLXIX = M + CD + L + X + IX.","Isso vale 1000+400+50+10+9=1469.","Em 2050 serão 2050−1469=581 anos: D."],"alternatives":{"A":"379 não corresponde à diferença entre 2050 e o ano romano 1469.","B":"381 decorre de leitura incorreta do bloco CD como adição, em vez de 500−100.","C":"579 não resulta da leitura correta de IX como nove e CD como quatrocentos.","D":"581 anos é a diferença correta entre 2050 e 1469.","E":"601 anos exige ler incorretamente algum bloco, como LX ou IX."},"takeaway":"Separe os pares subtrativos antes de somar os demais símbolos romanos.","key":"matematica:M175","area":"matematica","year":2021,"number":176,"answer":"D","subject":"Aritmética e Matemática básica","topic":"Operações, frações e sistemas de numeração","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[31],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Somar em decimal e converter fornece uma checagem","steps":["9+12=21 na base decimal.","21=16+4+1=2⁴+2²+2⁰.","Os algarismos nas posições 4,3,2,1,0 são 1,0,1,0,1: 10101, D."],"alternatives":{"A":"101₂ vale 4+1=5 na base decimal, e não a soma 21.","B":"1101₂ vale 8+4+1=13 na base decimal, abaixo da soma.","C":"1111₂ vale 8+4+2+1=15 na base decimal, e não 21.","D":"10101₂ vale 16+4+1=21, conferindo com 9+12.","E":"11001₂ vale 16+8+1=25 na base decimal, acima da soma."},"takeaway":"Na soma binária, 1+1 produz 0 na coluna e transporte de 1 à coluna seguinte.","key":"matematica:M176","area":"matematica","year":2021,"number":177,"answer":"D","subject":"Aritmética e Matemática básica","topic":"Operações, frações e sistemas de numeração","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[31],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Descontar ruas antes de contar lotes","steps":["A área comercializável é 3−0,9=2,1 ha=21000 m².","Dividindo por 300, obtêm-se 70 terrenos.","Receita=20·20000+50·30000=R$1900000, alternativa C."],"alternatives":{"A":"R$700000 não corresponde à venda dos 70 lotes nos dois preços.","B":"R$1600000 fica abaixo da receita dos 20 promocionais e 50 regulares.","C":"R$400000 dos primeiros vinte mais R$1500000 dos demais dão R$1900000.","D":"R$2200000 não respeita o total de 70 lotes após reservar a área das ruas.","E":"R$2800000 superestima a receita ao ignorar parte das condições de área e preços."},"takeaway":"Área de infraestrutura não pode ser vendida como lote; separe também as duas faixas de preço.","key":"matematica:M129","area":"matematica","year":2021,"number":178,"answer":"C","subject":"Aritmética e Matemática básica","topic":"Escalas e conversões de unidades","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[31],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Escolher materiais não exige ordená-los","steps":["Escolhem-se dois tecidos dentre seis: C(6,2).","Independentemente, escolhem-se cinco pedras dentre quinze: C(15,5).","Pelo princípio multiplicativo, C(6,2)·C(15,5)=6!/(4!2!)·15!/(10!5!), opção A."],"alternatives":{"A":"O produto de combinações escolhe os dois conjuntos sem contar ordens irrelevantes.","B":"A soma corresponderia a escolher tecidos ou pedras, não ambos.","C":"Além de somar, a expressão não elimina corretamente as ordens das escolhas.","D":"Faltam os fatores 4! e 10! para remover os elementos não escolhidos dos fatoriais.","E":"Escolher sete dentre 21 não assegura exatamente dois tecidos e cinco pedras."},"takeaway":"Use combinações para conjuntos sem ordem e multiplique escolhas que precisam ocorrer juntas.","key":"matematica:M757","area":"matematica","year":2021,"number":179,"answer":"A","subject":"Probabilidade e Análise combinatória","topic":"Contagem e análise combinatória","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[31],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Comparar custo por usuário, não custo total","steps":["Em quatro anos, A custa 180+4·60=420 mil; B custa 120+4·16=184 mil.","Divida pelas capacidades: A=420/100=4,2 mil por usuário; B=184/80=2,3 mil.","A economia por usuário é 4,2−2,3=1,9 mil reais: B."],"alternatives":{"A":"1,31 mil não resulta da diferença entre os dois custos unitários calculados.","B":"1,90 mil é a economia por usuário ao comparar os custos totais de quatro anos.","C":"2,30 mil é o custo por usuário do laboratório B, não a economia.","D":"2,36 mil divide a economia total de 236 mil por 100, ignorando a capacidade diferente de B.","E":"2,95 mil divide a diferença total por 80, também sem comparar os dois custos unitários."},"takeaway":"Com capacidades distintas, normalize cada custo antes de subtrair os indicadores.","key":"matematica:M819","area":"matematica","year":2021,"number":180,"answer":"B","subject":"Matemática financeira","topic":"Descontos, preços e comparação de propostas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://fisica.net/enem/provas/2021/ENEM-2021-GABARITO-DIA-02-azul.pdf","officialDocumentMirror":true,"officialKeyPDF":"/workspace/apostila-enem/matematica/gab_2021.pdf","sha256":"c78b77767c239fb93350f502f2f9f83bcadc7ae467d77b0a6cd887de8b5f4cc7","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/matematica/prova_2021.pdf","sourceExamPages":[31],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}}];
